 58|     const regions = [...new Set(apiaries.map((a) => a.region))].sort();
 59| 
 60|     const regionOfHive = new Map<string, string>();
 61|     for (const h of this.hives.findAll()) {
 62|       const region = regionOfApiary.get(h.apiaryId);
 63|       if (region !== undefined) regionOfHive.set(h.id, region);
 64|     }
 65|     const inQuarter = (date: string): boolean => {
 66|       const t = Date.parse(date);
 67|       return t >= start && t < end;
 68|     };
 69| 
 70|     return {
 71|       quarter: label,
 72|       regions: regions.map((region) => {
 73|         const hiveIds = [...regionOfHive].filter(([, r]) => r === region).map(([id]) => id);
 74|         const flagged = hiveIds.filter((id) => this.beekeeping.isFlagged(id, end)).length;
 75| 
 76|         const counts = new Map<string, number>();
 77|         for (const t of this.treatments.findAll()) {
 78|           if (regionOfHive.get(t.hiveId) === region && inQuarter(t.startDate)) {
 79|             counts.set(t.productId, (counts.get(t.productId) ?? 0) + 1);
 80|           }
 81|         }
 82|         const treatmentsPerProduct = [...counts].map(([productId, treatments]) => ({
 83|           productId,
 84|           product: this.products.findById(productId)?.name ?? productId,
 85|           treatments,
 86|         }));
 87| 
 88|         const honeyKilograms = this.harvests
 89|           .findAll()
 90|           .filter((h) => regionOfHive.get(h.hiveId) === region && inQuarter(h.date))
 91|           .reduce((sum, h) => sum + h.kilograms, 0);
 92| 
 93|         return {
 94|           region,
 95|           hives: hiveIds.length,
 96|           varroaFlaggedShare: hiveIds.length === 0 ? 0 : flagged / hiveIds.length,
 97|           treatmentsPerProduct,
 98|           honeyKilograms,
 99|         };
100|       }),
